1	// A discrete-event simulator of the tasks-dispatch spec (DESIGN.md), so the
2	// scenario play-throughs in SCENARIOS.md are executable instead of prose-only.
3	//
4	// What it models faithfully: virtual time, the scheduler run's jobs (the
5	// evaluate-at-anchor instantiation — precondition asked when the anchor comes,
6	// an item filed only on a yes, a no recorded as a row on the schedule board,
7	// fail-open on any read the scheduler cannot make — with both occurrence
8	// guards and the first-item rule; readiness; adoption; the executing-leash
9	// reclaim; the one-time sleeping-item migration), the schedule board as a
10	// modeled ARTIFACT (rows the engine actually writes, a write log, and the
11	// absent/corrupt degradations — never the rule's intent), the executor loop
12	// (pick order, same-title mutex, the `after` yield, claim, validate, the
13	// pick-time precondition re-evaluation whose no-go CLOSES the item — the roll
14	// is gone — the work step/hand-off/converge as timed phases, heartbeat
15	// comments during the work step so the leash measures executor death rather
16	// than work duration), at-most-once invocation (one call per item, never
17	// retried — the fired/refused/unanswered trichotomy of DESIGN §6.6), the
18	// readiness re-check on close (F1, reopened 2026-08-15), the janitor's
19	// stale-ready escalation, and the force lever (waking where an item exists,
20	// minting where none does — the common case once declines file nothing).
21	//
22	// What it deliberately does NOT model is inventoried in README.md's "The
23	// unsimulated world" — one row per boundary (cron delivery, list freshness,
24	// label non-atomicity, comment-id ordering, event delivery, secrets, …) with
25	// what defends the design there. A bug living exactly on one of those
26	// boundaries will not surface here; executor contention IS modeled, as
27	// stale-snapshot races over the claim protocol (raceExecutorsAt).
28	//
29	// Time is milliseconds UTC; events run strictly in time order (FIFO within a
30	// tie). Nothing here sleeps, threads, or reads the wall clock.
31	
32	const MIN = 60_000;
33	const HOUR = 60 * MIN;
34	const DAY = 24 * HOUR;
35	
36	export const T = (iso) => Date.parse(iso.length === 17 ? iso.replace('Z', ':00Z') : iso);
37	const iso = (t) => new Date(t).toISOString().slice(0, 16) + 'Z';
38	
39	// ---- frequency → anchors ----------------------------------------------------
40	// daily-Nh anchors at N:00Z, plain daily at 04:00Z, hourly at :00, weekly at
41	// Sunday 04:00Z. mostRecentAnchor is the latest anchor ≤ now; nextAnchor the
42	// earliest one > now.
43	
44	// daily-Nh / daily+Nh offset the schedule's daily hour (default 4), per the
45	// engine's DAILY_OFFSETS: daily-2h → 02:00Z, daily-1h → 03:00Z, daily → 04:00Z.
46	function anchorHour(frequency) {
47	  const m = /^daily([+-]\d+)h$/.exec(frequency);
48	  if (m) return 4 + Number(m[1]);
49	  if (frequency === 'daily') return 4;
50	  if (frequency === 'weekly') return 4;
51	  throw new Error(`no anchor hour for ${frequency}`);
52	}
53	
54	export function periodMs(frequency) {
55	  if (frequency === 'hourly') return HOUR;
56	  if (frequency === 'weekly') return 7 * DAY;
57	  return DAY; // daily, daily-Nh
58	}
59	
60	export function mostRecentAnchor(frequency, now) {
61	  if (frequency === 'manual') return null;
62	  if (frequency === 'hourly') return Math.floor(now / HOUR) * HOUR;
63	  const d = new Date(now);
64	  let a = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), anchorHour(frequency));
65	  if (a > now) a -= DAY;
66	  if (frequency === 'weekly') {
67	    while (new Date(a).getUTCDay() !== 0 || a > now) a -= DAY;
68	  }
69	  return a;
70	}
71	
72	export function nextAnchor(frequency, now) {
73	  let a = mostRecentAnchor(frequency, now);
74	  do a += periodMs(frequency); while (a <= now);
75	  return a;
76	}
77	
78	// ---- the simulator ----------------------------------------------------------
79	
80	// ---- the label vocabulary (DESIGN §4; the vocabulary migration, #1119) ------
81	// The sim WRITES canonical spellings only and DECODES every spelling ever
82	// written: open items created by a fielded engine wear the old labels, and the
83	// mechanism must react to them exactly as to its own. statusOf is that decode —
84	// one pass, straight to today's spelling.
85	export const STATUS_PREFIX = 'task:status:';
86	export const READY = 'task:status:waiting-for-executor';
87	export const NH = (kind) => `task:status:needs-human-${kind}`;
88	export const ORIGIN_PLANNED = 'task:origin:planned';
89	export const ORIGIN_AD_HOC = 'task:origin:ad-hoc';
90	export const ORIGIN_GITHUB = 'task:origin:github';
91	const TRIAGE = ['action', 'decision', 'approval', 'failure'];
92	// Legacy flat spellings → canonical. The legacy two-label park pair is handled
93	// in statusOf ahead of these (the sub-label decides; bare or unknown reads as
94	// failure, the conservative lane), because an old park kept its pair beside
95	// whatever state label a torn transition left behind.
96	const LEGACY_STATUS = new Map([
97	  ['task:blocked', 'task:status:blocked'],
98	  ['task:ready', READY],
99	  ['task:executing', 'task:status:running-executor'],
100	  ['task:agent', 'task:status:running-agent'],
101	  ['task:done', 'task:status:done'], ['outcome:done', 'task:status:done'],
102	  ['task:obsolete', 'task:status:rejected'], ['outcome:obsolete', 'task:status:rejected'],
103	]);
104	export function statusOf(i) {
105	  for (const l of i.labels) if (l.startsWith(STATUS_PREFIX)) return l;
106	  for (const l of i.labels) {
107	    const m = /^task:needs-human-(.+)$/.exec(l);
108	    if (m) return NH(TRIAGE.includes(m[1]) ? m[1] : 'failure');
109	  }
110	  if (i.labels.has('needs-human')) return NH('failure');
111	  for (const l of i.labels) { const c = LEGACY_STATUS.get(l); if (c) return c; }
112	  return null;
113	}
114	export const REQUEST_TASK = 'engine/implement-request';
115	export const MODEL_FAMILIES = ['opus', 'sonnet', 'haiku'];
116	export const DEFAULT_MODEL = 'opus';
117	// Push permission, read from the permission API (F30). The payload's
118	// `author_association` alone is broader than push — MEMBER is any org member and
119	// COLLABORATOR includes read-only collaborators — so it may prefilter, but the
120	// verdict is the permission read, which is what the sim models.
121	export const PUSH_PERMISSIONS = ['admin', 'maintain', 'write'];
122	export const APPROVAL_RE = /^\s*\/claude\s+go\b/im;
123	
124	// Eligibility over one request's payload — the built-in precondition's core,
125	// modeled here in the shape the engine will carry it: candidate logins (the
126	// author, then approving commenters) judged by their permission on the repo.
127	export function eligible(req, permissionOf) {
128	  if (PUSH_PERMISSIONS.includes(permissionOf(req.author))) return { ok: true, why: `opened by ${req.author}, who has push access` };
129	  const approval = (req.comments ?? []).find((c) => APPROVAL_RE.test(c.body ?? '') && PUSH_PERMISSIONS.includes(permissionOf(c.login)));
130	  if (approval) return { ok: true, why: `approved by ${approval.login} with /claude go` };
131	  return { ok: false, why: 'neither opened nor approved by anyone with push access' };
132	}
133	
134	// The model a request asks for — a BODY parameter now, not a label, honored
135	// only when the issue AUTHOR holds push access (the body is author-editable
136	// where a label is write-gated). An unrecognized family falls back to the
137	// default rather than to nothing — a request nobody can run would look
138	// accepted forever — and an ungated author's ask runs at the default too.
139	export function gatedModel(req, permissionOf) {
140	  if (!PUSH_PERMISSIONS.includes(permissionOf(req.author))) return DEFAULT_MODEL;
141	  return MODEL_FAMILIES.includes(req.model) ? req.model : DEFAULT_MODEL;
142	}
143	
144	export function makeSim({
145	  tasks,
146	  schedulerRunMinute = 17,
147	  executingLeashMs = 1 * HOUR,
148	  agentLeashMs = 3 * HOUR,
149	  heartbeatMinutes = 15, // the executor's activity comment cadence during the work step
150	  pickSeed = 1, // seed for the randomized pick order, so scenarios replay identically
151	  staleReadyPeriods = 2,
152	  staleBlockedMs = 2 * DAY,
153	  heartbeatsDisabled = false, // S31b only: demonstrate the livelock heartbeats prevent
154	  collaborators = { owner: 'admin' }, // login -> repo permission, as the permission API answers (F30)
155	} = {}) {
156	  const registry = new Map(tasks.map((t) => [t.id, t]));
157	  const permissionOf = (login) => collaborators[login] ?? 'none';
158	  // Ordinary issues somebody marked. Under the one-issue model the marked
159	  // issue BECOMES the work item at adoption — the item record shares the
160	  // issue's label Set, so a status written on one is written on both, which is
161	  // the artifact-level truth of "the issue is the item".
162	  const requests = []; // {number,labels:Set,state,author,model,unreadable,comments:[{login,body}]}
163	  // A deleted issue ('gone') is invisible here, exactly as a 404 makes it: the
164	  // precondition sees "does not exist", and no write-back can reach it.
165	  const requestOf = (n) => requests.find((r) => r.number === n && r.state !== 'gone') ?? null;
166	  const titleOf = (id) => `[claudinite-work] ${id}`;
167	
168	  // The built-in request task, always present wherever the queue runs (DESIGN
169	  // §16.2): `manual`, so the scheduler run never puts it on a calendar — an item exists
170	  // only because an issue was marked. Its precondition IS the security check, and
171	  // it declares no code-work at all, so a request goes issue → item → agent with
172	  // nothing in between to carry a payload.
173	  registry.set(REQUEST_TASK, {
174	    id: REQUEST_TASK,
175	    frequency: 'manual',
176	    agentMinutes: 45,
177	    ceiling: 'open-pr',
178	    deliversOpenPr: () => true,           // every successful run leaves a PR to review
179	    // Evaluated at pickup like every other precondition, and — the one addition
180	    // the contract needs — over THIS item, because which request it is about is a
181	    // property of the item, not of the task.
182	    precondition: (_world, _now, item) => {
183	      const req = requestOf(item?.request);
184	      // Transiently unreadable is NOT a verdict (F27): a decline's write-back
185	      // cannot reach an issue it cannot read, so declining here would strand
186	      // `claude-queued` forever over nothing. It surfaces as a run FAILURE —
187	      // the executor parks the item in the failure lane, open and retryable.
188	      if (req?.unreadable) return { error: `issue #${req.number} could not be read — refusing to guess` };
189	      if (!req) return { run: false, reason: `issue #${item?.request} does not exist` };
190	      if (req.state !== 'open') return { run: false, reason: `issue #${req.number} was closed before this ran` };
191	      if (!req.labels.has(ORIGIN_AD_HOC)) return { run: false, reason: `issue #${req.number} no longer carries the mark — the request was withdrawn` };
192	      const verdict = eligible(req, permissionOf);
193	      return verdict.ok
194	        ? { run: true, reason: `#${req.number}: ${verdict.why}` }
195	        : { run: false, reason: `#${req.number}: ${verdict.why}` };
196	    },
197	  });
198	
199	  // F17, reframed by the work-as-work review (2026-08-15): the leash no longer
200	  // has to exceed every task's work bound — heartbeat comments during the work
201	  // step keep a LIVE executor's item out of the reclaim, however long the work
202	  // runs, so the leash measures executor death, not work duration. The wiring
203	  // constraint that remains is the one the heartbeat itself needs: the
204	  // heartbeat interval must sit well inside the leash, or every heartbeat
205	  // arrives too late to matter.
206	  if (heartbeatMinutes * MIN >= executingLeashMs) {
207	    throw new Error(
208	      `heartbeat interval (${heartbeatMinutes}m) reaches the executing leash — F17 (reframed)`);
209	  }
210	
211	  const issues = []; // {number,title,taskId,labels:Set,state,createdAt,closedAt,readySince,lastActivity,notBefore,blockedBy:[],outcome,rolls:[],comments:[],escalated,sessions:[],quarantined}
212	  const log = []; // {t,kind,task,issue,...}
213	
214	  // ---- the schedule board (DESIGN §5, decision §15.28) ----------------------
215	  // Modeled as what the engine WRITES: one issue (`[claudinite-schedule]`),
216	  // whose body is a table of rows — one per scheduled task — parsed back on
217	  // every scheduler run as the watermark. `exists`/`corrupt` model the two
218	  // degradations the design must survive: a deleted board reads as absent, a
219	  // mangled body degrades to absent per-row; both fail toward evaluating.
220	  // A write REPLACES the body from the rows this run could parse plus the rows
221	  // it changed — so a corrupt board's unparsable rows are genuinely lost on
222	  // the next write, which is the artifact-level truth a rows-always-survive
223	  // model would hide.
224	  const board = { exists: false, corrupt: false, rows: new Map() }; // taskId -> {frequency,lastAsked,verdict,reason}
225	  const boardRow = (taskId) => (!board.exists || board.corrupt ? null : board.rows.get(taskId) ?? null);
226	  // The change test compares the AUTHORITATIVE columns only (last asked,
227	  // verdict, reason) — never the derived next-window column, which is
228	  // recomputed at write time and would otherwise turn every scheduler run into a
229	  // rewrite (F31, caught by S58 against a body-diff first cut).
230	  function writeBoardRow(taskId, frequency, lastAsked, verdict, reason) {
231	    const prev = boardRow(taskId);
232	    if (prev && prev.lastAsked === lastAsked && prev.verdict === verdict && prev.reason === reason) return;
233	    if (!board.exists) { board.exists = true; record('board-create', {}); }
234	    if (board.corrupt) { board.rows.clear(); board.corrupt = false; } // rewrite replaces the mangled body
235	    board.rows.set(taskId, { frequency, lastAsked, verdict, reason });
236	    record('board-write', { task: taskId, verdict, lastAsked: iso(lastAsked) });
237	  }
238	  // Which tasks the scheduler cannot collect signals for (a missing
239	  // credential) — the fail-open lever the scenarios pull.
240	  const signalsUnavailable = new Set();
241	  // The issue-creation API refuses the next create for these tasks (a 4xx/5xx
242	  // on the POST) — the write-failure half of F31's scenario.
243	  const failNextCreateOf = new Set();
244	  const world = {}; // scenario-owned signal state, read by precondition fns
245	  const queue = []; // {t,seq,fn}
246	  let seq = 0;
247	  let now = 0;
248	  let sessionSeq = 0;
249	  // Randomized pick order (owner, 2026-08-15) wants randomness; reproducible
250	  // tests want determinism. A seeded LCG gives both.
251	  let prngState = pickSeed >>> 0;
252	  const prng = () => (prngState = (prngState * 1664525 + 1013904223) >>> 0) / 2 ** 32;
253	  // CLAUDINITE_TASKS_SUSPEND_ALL (owner, 2026-08-16): a repo Actions variable
254	  // every Claudinite workflow checks as its FIRST act — when true, the run
255	  // exits cleanly and fires nothing, so the train parks at most one hop after
256	  // suspension. Gates workflow STARTS only: in-flight runs and agent sessions
257	  // finish on their own, and items freeze in place with no labels touched.
258	  let suspendedAll = false;
259	  const crashNextOf = new Set(); // taskIds whose next execution dies mid-claim
260	  const crashDuringWorkOf = new Map(); // taskId -> minutes into the work step the runner dies
261	  const crashAgentOf = new Set(); // taskIds whose next agent session dies mid-run
262	
263	  const schedule = (t, fn) => queue.push({ t, seq: seq++, fn });
264	  const record = (kind, extra) => log.push({ t: now, at: iso(now), kind, ...extra });
265	
266	  const open = () => issues.filter((i) => i.state === 'open');
267	  const has = (i, l) => i.labels.has(l);
268	  // The ORIGIN LABEL is the authority on standing vs ad-hoc (DESIGN §3, owner
269	  // 2026-08-20, reversing 2026-08-19's marker-free rule): `task:origin:planned`
270	  // marks the task's calendar occurrence, everything else is ad-hoc. The
271	  // structural read — bare unqualified title of a task with a frequency at
272	  // HEAD — survives only as the decode fallback for items that predate the
273	  // scheme and carry no origin at all.
274	  const family = (taskId) => issues.filter((i) => i.title === titleOf(taskId));
275	  const isStanding = (i) => {
276	    const o = originOf(i);
277	    if (o) return o === ORIGIN_PLANNED;
278	    const task = registry.get(i.taskId);
279	    return !!task && task.frequency !== 'manual' && i.title === titleOf(i.taskId);
280	  };
281	  const standingItem = (taskId) => family(taskId).find((i) => i.state === 'open');
282	
283	  // A park is ONE label (DESIGN §4, the vocabulary migration): the machine
284	  // filters on the `task:status:needs-human-` prefix and a person reads the
285	  // kind off the same label's tail. The legacy two-label pair decodes through
286	  // statusOf, modeled there because that is what old items actually wear —
287	  // modeling only the intent is the blind spot that hid F24.
288	  const triageLabel = (kind) => NH(TRIAGE.includes(kind) ? kind : 'failure');
289	  const park = (it, _from, kind) => setStatus(it, triageLabel(kind));
290	  // The road back clears the status, restoring the no-status shape; the
291	  // re-queue lever then applies the ready status explicitly.
292	  const unpark = (it) => clearStatus(it);
293	  const isParked = (i) => (statusOf(i) ?? '').startsWith(NH(''));
294	  // Only a fault park holds the task's lane — and the decode sends a bare
295	  // legacy park and every unknown kind here, the direction that must be safe.
296	  const blockingPark = (i) => statusOf(i) === NH('failure');
297	
298	  function createIssue({ taskId, labels, notBefore = null, blockedBy = [], urgent = false, qualifier = null, request = null, model = null, origin = ORIGIN_PLANNED }) {
299	    const it = {
300	      request, model,
301	      number: issues.length + 900,
302	      title: titleOf(taskId) + (qualifier ? ` ${qualifier}` : ''),
303	      taskId,
304	      labels: new Set(labels.concat(urgent ? ['task:urgent'] : []).concat(origin ? [origin] : [])),
305	      state: 'open',
306	      createdAt: now, closedAt: null,
307	      readySince: labels.includes('task:status:waiting-for-executor') ? now : null,
308	      lastActivity: now,
309	      notBefore, blockedBy,
310	      outcome: null, rolls: [], comments: [], escalated: false,
311	      sessions: [], quarantined: false,
312	    };
313	    issues.push(it);
314	    record('create', { task: taskId, issue: it.number });
315	    return it;
316	  }
317	
318	  // Statuses are mutually exclusive: a write clears every spelling of every
319	  // status — canonical, legacy flat, legacy pair — before adding the new one,
320	  // so a decoded legacy item comes out canonical from its first transition.
321	  function clearStatus(it) {
322	    for (const l of [...it.labels]) {
323	      if (l.startsWith(STATUS_PREFIX) || LEGACY_STATUS.has(l)
324	        || l === 'needs-human' || l.startsWith('task:needs-human-')) it.labels.delete(l);
325	    }
326	  }
327	  function setStatus(it, to) {
328	    clearStatus(it);
329	    it.labels.add(to);
330	    it.readySince = to === READY ? now : null;
331	    it.lastActivity = now;
332	  }
333	  const is = (i, status) => statusOf(i) === status;
334	  const originOf = (i) => [...i.labels].find((l) => l.startsWith('task:origin:')) ?? null;
335	
336	  // F18/F24: the episode boundary is an ARTIFACT on the item, not a property of
337	  // the label transition. Modelling it as "every transition into ready opens a
338	  // new episode" is what made this simulator unable to reproduce F24: it encoded
339	  // the rule's intent, so the paths that end an episode without writing anything
340	  // looked correct here and livelocked in production. So the epoch advances
341	  // exactly where the engine leaves a mark — the scheduler run's reclaim, the F15 revert,
342	  // and the departing executor's strike on a roll or a park (DESIGN §6.2).
343	  //
344	  // A human re-queue deliberately does NOT advance it: a human editing labels
345	  // writes no comment, which is precisely why the strike has to have happened
346	  // already.
347	  function endEpisode(it) { it.claimEpoch = seq++; }
348	
349	  function close(it, outcome) {
350	    it.state = 'closed';
351	    it.closedAt = now;
352	    it.outcome = outcome;
353	    // the terminal status goes ON; urgency ends with the item; the ORIGIN stays
354	    // for life — the closed issue keeps saying where it came from
355	    clearStatus(it);
356	    it.labels.delete('task:urgent');
357	    it.labels.add(outcome === 'done' ? 'task:status:done' : 'task:status:rejected');
358	    record('close', { task: it.taskId, issue: it.number, outcome });
359	    // F1, reopened 2026-08-15: whoever closes an item — executor or agent —
360	    // also re-checks blocked items' readiness in code (Blocked-by all closed,
361	    // Not-before passed) and a drain follows, so chain links proceed in
362	    // minutes instead of waiting out the scheduler run. The scheduler run's readiness job stays
363	    // the backstop; a HAND close runs no engine code and is covered by it.
364	    for (const b of open().filter((i) => is(i, 'task:status:blocked'))) {
365	      const blockersDone = b.blockedBy.every(
366	        (n) => issues.find((x) => x.number === n)?.state === 'closed'
367	      );
368	      if (blockersDone && (b.notBefore === null || now >= b.notBefore)) {
369	        setStatus(b, 'task:status:waiting-for-executor');
370	        record('ready', { task: b.taskId, issue: b.number, by: 'close' });
371	      }
372	    }
373	    if (pickable().length > 0) {
374	      schedule(now + 1 * MIN, () => executorRun('E1', 'close-drain'));
375	    }
376	  }
377	
378	  // ---- the scheduler run (DESIGN §5): decides at the anchor, files only work ----
379	  function schedulerRun() {
380	    if (suspendedAll) { record('suspended-skip', { workflow: 'scheduler-run' }); return; }
381	    record('scheduler-run', {});
382	    // one-time migration (#1115): the sleeping standing items the roll model
383	    // left behind — open, blocked, a FUTURE Not-before, no blockers, a roll on
384	    // record — close with a comment, their last verdict seeded onto the board.
385	    // Idempotent by construction: a closed item never matches again, and a
386	    // seeded row is written only where none exists. Items waiting on a blocker
387	    // or on a first-ever/adoption Not-before (no roll on record) are untouched.
388	    for (const it of open().filter((i) => is(i, 'task:status:blocked'))) {
389	      if (!isStanding(it) || it.blockedBy.length || it.rolls.length === 0) continue;
390	      if (it.notBefore === null || it.notBefore <= now) continue;
391	      const last = it.rolls.at(-1);
392	      if (!boardRow(it.taskId)) {
393	        writeBoardRow(it.taskId, registry.get(it.taskId)?.frequency ?? null, last.t, 'no', last.reason);
394	      }
395	      it.comments.push({ t: now, body: 'closing: declined occurrences now live on the schedule board, not as sleeping items' });
396	      close(it, 'rejected');
397	      record('migrate-sleeping', { task: it.taskId, issue: it.number });
398	    }
399	    // job 1: instantiate — the precondition is asked WHEN THE ANCHOR COMES,
400	    // and an item is filed only on a yes (owner, 2026-08-20, #1115). A no is a
401	    // board row; a read the scheduler cannot make fails OPEN — the item is
402	    // created exactly as the calendar-only model did, and the executor (which
403	    // holds the credentials) decides at pick. Never fewer runs because a read
404	    // failed.
405	    for (const task of registry.values()) {
406	      if (task.frequency === 'manual') continue;
407	      const A = mostRecentAnchor(task.frequency, now);
408	      const fam = family(task.id);
409	      // F16 self-heal: if a stale issue list ever let a duplicate standing
410	      // item through (nothing guarantees a REST list from another node sees a
411	      // creation seconds old), close every open one but the oldest. The scheduler run
412	      // is serialized (concurrency group), so this cannot race itself.
413	      // A park that is somebody's inbox rather than a fault is neither the
414	      // standing item nor a duplicate of one, so it leaves both tests and the
415	      // schedule goes on around it (#1032: conflating them parked Shepherd's
416	      // fleet-digest for two days behind one permission gap). It stays in `fam`
417	      // for the occurrence guard below — it DID consume its own occurrence.
418	      const openFam = fam.filter((i) => i.state === 'open')
419	        .filter((i) => !isParked(i) || blockingPark(i))
420	        .sort((a, b) => a.number - b.number);
