555	  // ---- the executor (DESIGN §6) ---------------------------------------------
556	  function pickable() {
557	    const ready = open().filter((i) => is(i, 'task:status:waiting-for-executor'));
558	    const live = (taskId) => {
559	      const s = standingItem(taskId);
560	      return s && ['task:status:waiting-for-executor', 'task:status:running-executor', 'task:status:running-agent'].some((l) => has(s, l));
561	    };
562	    return ready
563	      .filter((i) => !i.quarantined) // an item no live executor can reach (S18)
564	      .filter((i) => {
565	        // same-title mutex: one task, one execution at a time
566	        if (open().some((o) => o !== i && o.title === i.title &&
567	              (is(o, 'task:status:running-executor') || is(o, 'task:status:running-agent')))) return false;
568	        // the `after` yield: skip while the upstream's standing item is live
569	        // this cycle (a rolled or needs-human upstream does not block — S23)
570	        if (isStanding(i)) {
571	          const ups = registry.get(i.taskId)?.after ?? [];
572	          if (ups.some((up) => live(up))) return false;
573	        }
574	        return true;
575	      })
576	      .map((i) => ({ i, r: prng() }))
577	      // urgent first, then RANDOM among the ready (owner, 2026-08-15) — two
578	      // executors listing the same queue then contend on DIFFERENT heads, and
579	      // nothing leaned on oldest-first: the stale-ready escalation is
580	      // period-scale, indifferent to minute-scale pick reordering
581	      .sort((a, b) =>
582	        (has(b.i, 'task:urgent') ? 1 : 0) - (has(a.i, 'task:urgent') ? 1 : 0) ||
