587	  // The claim is the verified lease (DESIGN §6.2): swap, post a claim
588	  // comment, re-read — earliest comment wins, the loser reverts nothing and
589	  // moves on. `preRead` is the label state the executor saw when it read the
590	  // item; a racing executor's stale read is modeled by passing the snapshot
591	  // taken before the rival's swap landed.
592	  function claim(it, execId, preRead) {
593	    if (statusOf({ labels: preRead }) !== READY) return false;
594	    setStatus(it, 'task:status:running-executor');
595	    it.readySince = null;
596	    it.lastActivity = now;
597	    it.comments.push({ t: now, seq: seq++, kind: 'claim', exec: execId });
598	    // F18: arbitrate only among THIS episode's claims — earliest since the
599	    // item last became ready, by server-assigned comment order
600	    const claims = it.comments.filter((c) => c.kind === 'claim' && c.seq > (it.claimEpoch ?? -1));
601	    const won = claims[0].exec === execId;
602	    record(won ? 'claim' : 'claim-lost', { task: it.taskId, issue: it.number, exec: execId });
603	    return won; // loser reverts nothing — the winner's labels already stand
