619	  // sessions can never arrive at one item, so there is nothing to arbitrate.
620	  function handOff(it, task) {
621	    setStatus(it, 'task:status:running-agent');
622	    if (world._apiRefusedUntil != null && now < world._apiRefusedUntil) {
623	      record('handoff-refused', { task: it.taskId, issue: it.number });
624	      park(it, 'task:status:running-agent', 'action'); // a token, a URL or a routine is wrong
625	      return;
626	    }
627	    if (world._apiUnanswered) {
628	      const { started } = world._apiUnanswered;
629	      world._apiUnanswered = null;
630	      record('handoff-unanswered', { task: it.taskId, issue: it.number, started });
631	      it.comments.push({ t: now, body: 'invocation got no answer — outcome unknown, the agent leash decides' });
632	      if (!started) return; // silent item; the janitor's agent leash is the recovery
633	      const s = { id: `s-${++sessionSeq}`, item: it.number };
634	      it.sessions.push(s);
635	      schedule(now + 30_000, () => startAgentSession(s, it, task));
636	      return;
637	    }
638	    record('handoff', { task: it.taskId, issue: it.number });
639	    const s = { id: `s-${++sessionSeq}`, item: it.number };
640	    it.sessions.push(s);
641	    schedule(now + 30_000, () => startAgentSession(s, it, task));
642	  }
