644	  function startAgentSession(s, it, task) {
645	    if (it.state !== 'open' || !is(it, 'task:status:running-agent')) return;
646	    // No agent-side claim (DESIGN §7, amended 2026-08-15): the session checks,
647	    // not claims — the item wears task:status:running-agent and the fire's nonce matches the
648	    // newest hand-off, both modeled by the guard above.
649	    it.lastActivity = now;
650	    if (crashAgentOf.delete(it.taskId)) {
651	      record('agent-died', { task: it.taskId, issue: it.number, session: s.id });
652	      return; // never converges; the janitor's agent leash is the recovery (S11)
653	    }
654	    schedule(now + task.agentMinutes * MIN, () => {
655	      if (it.state !== 'open') return;
656	      if (task.agentFails?.(world, now)) {
657	        park(it, 'task:status:running-agent', 'failure');
658	        record('agent-failed', { task: it.taskId, issue: it.number });
659	        return;
660	      }
661	      // The agentic mirror of the code-work approval park below: a SESSION that
662	      // deliberately left an unmerged PR is in the same position as a worker that
663	      // did — succeeded, not finished, waiting on a named reviewer. Modeled here
664	      // because the request task is the first agentic task whose every successful
665	      // run ends that way.
666	      if (task.deliversOpenPr?.(world, now)) {
667	        park(it, 'task:status:running-agent', 'approval');
668	        record('delivered-open-pr', { task: it.taskId, issue: it.number });
669	        return;
670	      }
671	      close(it, task.outcome ?? 'done');
672	    });
673	  }
