675	  // One claimed item through to its settle. `onSettled` is the RUN's
676	  // continuation — called when the item stops occupying this executor (roll,
677	  // close, hand-off, work failure), and deliberately NOT called when the
678	  // runner itself dies (the run died with it; the leash is the recovery).
679	  // The hand-off settles the item for the run: the executor never waits for
680	  // the agent, which is why agent work parallelizes and executor work is the
681	  // occupancy (DESIGN §10).
682	  function executeClaimed(it, task, onSettled = () => {}) {
