684	      record('executor-crash', { task: it.taskId, issue: it.number });
685	      // The workflow's failure-continuation job (needs: execute, if:
686	      // failure() || cancelled()) re-dispatches on a fresh runner, so a dead
687	      // run never stalls the train — the crashed ITEM still waits for the
688	      // leash reclaim; only the QUEUE keeps moving (S36).
