841	    endEpisode(it);
842	    setStatus(it, 'task:status:waiting-for-executor');
843	    record('claim-reverted', { task: it.taskId, issue: it.number, exec: execId });
844	    return false;
845	  }
846	
847	  // One executor RUN — a workflow run in the real deployment — performs ONE
848	  // item. Not a configured maximum: the essence of the executor (owner,
849	  // 2026-08-15). The run claims an item, sees it through to its settle (roll,
850	  // close, hand-off, failure), and ends; if the queue still has pickable
851	  // items it RE-DISPATCHES a fresh run (`workflow_dispatch`, which the
852	  // default GITHUB_TOKEN may fire), so the queue drains run by run and a
853	  // run's timeout sizes to a single work bound. Every run records its
854	  // trigger — scheduler-run-drain | label-event | close-drain | re-dispatch |
855	  // failure-redispatch — so tests assert WHAT caused each run, not just that
856	  // items converged.
857	  let runSeq = 0;
858	  function executorRun(execId = 'E1', trigger = 'label-event') {
859	    if (suspendedAll) { record('suspended-skip', { workflow: 'executor', trigger }); return; }
860	    const runId = `R${++runSeq}`;
861	    record('executor-run', { run: runId, exec: execId, trigger });
862	    const settle = () => {
863	      record('run-end', { run: runId, exec: execId, trigger, settled: 1 });
864	      if (pickable().length > 0) {
865	        schedule(now + 1 * MIN, () => executorRun(execId, 're-dispatch'));
866	      }
867	    };
868	    const step = () => { // claim attempts until one item is held, or the queue is empty
869	      const it = pickable()[0];
870	      if (!it) { record('run-end', { run: runId, exec: execId, trigger, settled: 0 }); return; }
871	      if (!claim(it, execId, new Set(it.labels))) return step(); // loser tries another item
872	      if (!postClaimVerify(it, execId)) return step();
873	      const task = registry.get(it.taskId);
874	      if (!task) { close(it, 'rejected'); return settle(); } // validate: task gone (S20)
875	      record('pick', { run: runId, exec: execId, task: it.taskId, issue: it.number });
876	      executeClaimed(it, task, settle);
877	    };
878	    step();
879	  }
880	
881	  // ---- the janitor (DESIGN §11): the judgment-and-long-horizon sweeps -------
882	  function janitor() {
883	    if (suspendedAll) { record('suspended-skip', { workflow: 'janitor' }); return; }
884	    // rule A — stale-ready: an item no executor picked for ~2 periods comes
885	    // out of the queue as a human's problem (S18's stuck member)
886	    for (const it of open().filter((i) => is(i, 'task:status:waiting-for-executor') && !i.escalated)) {
887	      const per = registry.has(it.taskId) ? periodMs(registry.get(it.taskId).frequency) : DAY;
888	      if (it.readySince !== null && now - it.readySince >= staleReadyPeriods * per) {
889	        it.escalated = true;
890	        park(it, 'task:status:waiting-for-executor', 'action'); // the lane is not draining; the fix is outside the item
891	        record('escalate', { task: it.taskId, issue: it.number, rule: 'stale-ready' });
892	      }
893	    }
894	    // rule B — the agent leash: task:status:running-agent silent past ~3h means the session
895	    // died; converge needs-human, naming the dead session (S11)
896	    for (const it of open().filter((i) => is(i, 'task:status:running-agent'))) {
897	      if (now - it.lastActivity >= agentLeashMs) {
898	        const dead = it.sessions.at(-1)?.id ?? 'unknown';
899	        // what the dead session left behind decides whether this re-queues
900	        park(it, 'task:status:running-agent', 'decision');
901	        it.comments.push({ t: now, body: `agent session ${dead} went silent past the leash` });
902	        record('agent-reclaim', { task: it.taskId, issue: it.number, session: dead });
903	      }
904	    }
905	    // rule C — stuck dependency (F14): a blocked item whose blockers have not
906	    // resolved for ~2 days is surfaced with an escalation COMMENT — labels
907	    // stay untouched, so the item still proceeds by itself the moment its
908	    // blockers resolve. Sleeping items (future Not-before, blockers closed)
909	    // and rolling items (no blockers) never match.
910	    for (const it of open().filter((i) => is(i, 'task:status:blocked') && !i.escalated)) {
911	      const blocked = it.blockedBy.some((n) => issues.find((x) => x.number === n)?.state !== 'closed');
912	      if (blocked && now - it.createdAt >= staleBlockedMs) {
913	        it.escalated = true;
914	        it.comments.push({ t: now, body: 'stuck: blockers unresolved past the bound' });
915	        record('escalate', { task: it.taskId, issue: it.number, rule: 'stuck-dependency' });
916	      }
917	    }
918	  }
919	
920	  // ---- the scenario DSL -----------------------------------------------------
921	  const droppedSchedulerRuns = [];
922	  const sim = {
923	    issues, log, world, requests,
924	    requestItems: () => issues.filter((i) => i.request != null),
925	    requestIssue: (n) => requestOf(n),
926	
927	    // A person marks an ordinary issue (DESIGN §16.1). `author` is the issue
928	    // author's login — the precondition judges its repo permission — and `model`
929	    // the optional family label. No latency sugar: adoption is the scheduler run's job,
930	    // so a mark waits for the next one.
931	    markIssue({ author = 'owner', model = null, comments = [] } = {}) {
932	      const req = {
933	        number: requests.length + 500,
934	        labels: new Set([ORIGIN_AD_HOC]),
935	        state: 'open', author, model, comments: [...comments],
936	      };
937	      requests.push(req);
938	      record('mark', { issue: req.number, author, model });
939	      return req;
940	    },
941	    // A person withdraws a request after it was adopted, or closes the issue.
942	    withdrawRequest(number) { requestOf(number).labels.delete(ORIGIN_AD_HOC); return sim; },
943	    closeRequestIssue(number) {
944	      const req = requestOf(number); req.state = 'closed';
945	      const it = issues.find((i) => i.request === number && i.state === 'open');
946	      if (it) { it.state = 'closed'; it.closedAt = now; } // one issue: closing it closes the item
947	      return sim;
948	    },
949	    // The issue stops existing (a 404): reads answer "not there", writes reach
950	    // nothing. Distinct from unreadable below — gone is a fact, not a fault.
951	    deleteRequestIssue(number) {
952	      const req = requestOf(number); req.state = 'gone';
953	      const it = issues.find((i) => i.request === number && i.state === 'open');
954	      if (it) it.state = 'gone';
955	      return sim;
956	    },
957	    // A transient API failure: the issue exists but cannot be read right now.
958	    setRequestUnreadable(number, on = true) { requestOf(number).unreadable = on; return sim; },
959	    // Re-marking an issue — the phone-sized way to ask again; adoption
960	    // supersedes a parked predecessor (F28), and the item-side re-queue lever
961	    // (DESIGN §4) remains the other sanctioned retry.
962	    // The phone-sized re-ask: clear the status, leaving the bare mark — the
963	    // next scheduler run re-adopts the same record. One lever for park,
964	    // rejection and review alike.
965	    remarkIssue(number, { model = null } = {}) {
966	      const req = requestOf(number);
967	      const st = statusOf(req);
968	      const settled = st === null || st.startsWith(NH('')) || st === 'task:status:rejected' || st === 'task:status:done';
969	      // While the run is LIVE there is nothing to ask again — the mark already
970	      // stands and the status says a run owns it, so an impatient re-ask
971	      // changes nothing (the one-issue mirror of "the mark waits, unconsumed").
972	      if (!settled) { record('mark', { issue: number, remark: true, refused: 'live' }); return req; }
973	      if (st !== null) clearStatus(req);
974	      req.labels.add(ORIGIN_AD_HOC);
975	      if (model) req.model = model;
976	      record('mark', { issue: number, remark: true });
977	      return req;
978	    },
979	    family, standingItem,
980	
981	    // "at time X, Y happens"
982	    at(isoTime, fn) { schedule(T(isoTime), () => fn(sim)); return sim; },
983	
984	    // GitHub drops scheduled fires in [from, to) — the scheduler runs simply don't run
985	    dropSchedulerRuns(fromIso, toIso) { droppedSchedulerRuns.push([T(fromIso), T(toIso)]); return sim; },
986	    // one late/manual scheduler run outside the cron grid (with its post-scheduler run drain)
987	    schedulerRunAt(isoTime) {
988	      schedule(T(isoTime), schedulerRun);
989	      schedule(T(isoTime) + 40_000, () => executorRun('E1', 'scheduler-run-drain'));
990	      return sim;
991	    },
992	
993	    // an established repo: every scheduled task already ran its previous
994	    // occurrence (a closed done item), so the first-item rule doesn't apply
995	    seedSteadyState(asOfIso) {
996	      const t0 = T(asOfIso);
997	      for (const task of registry.values()) {
998	        if (task.frequency === 'manual') continue;
999	        const a = mostRecentAnchor(task.frequency, t0);
1000	        issues.push({
1001	          number: issues.length + 800, title: titleOf(task.id), taskId: task.id,
1002	          labels: new Set(), state: 'closed',
1003	          createdAt: a, closedAt: a + 30 * MIN, readySince: null, lastActivity: a,
1004	          notBefore: null, blockedBy: [], outcome: 'done', rolls: [], comments: [],
1005	          escalated: false, seeded: true,
1006	        });
1007	      }
1008	      return sim;

