1	// SCENARIOS.md, executable. Each test is a timed play-through against the
2	// simulator in sim.mjs: "at time X, Y happens", then run the virtual clock and
3	// assert on the issue store and the event log. Scenario numbers match the
4	// prose document (§H's standing-item replay + the stable earlier scenarios);
5	// a test here going red means the DESIGN.md mechanism, as modeled, breaks.
6	//
7	// The cast mirrors SCENARIOS.md's "Cast and constants" table. Preconditions
8	// read `world`, the scenario-owned signal state — task questions only, never
9	// calendar ones (DESIGN §6.4).
10	
11	import test from 'node:test';
12	import assert from 'node:assert/strict';
13	import { makeSim, T, NH, READY, ORIGIN_AD_HOC, ORIGIN_PLANNED, statusOf } from './sim.mjs';
14	
15	// a park is one status label now; these read it the way the machine does
16	const isParked = (it) => (statusOf(it) ?? '').startsWith(NH(''));
17	
18	function cast() {
19	  return [
20	    {
21	      id: 'basics/baselining', frequency: 'daily-2h', outcome: 'done',
22	      codeWorkMinutes: 21, agentMinutes: 30,
23	      precondition: (w) => ({ run: !!w.mountBehind, reason: 'mount converged, no pending notes' }),
24	      requestsAgent: (w) => !!w.baseliningNeedsJudgment,
25	      codeWorkFails: (w) => !!w.mountBroken,
26	    },
27	    {
28	      id: 'grow/growth-extract', frequency: 'daily-1h', after: ['basics/baselining'],
29	      outcome: 'done', codeWorkMinutes: 2, agentMinutes: 35,
30	      precondition: (w) => ({ run: !!w.extractHasLessons, reason: 'nothing new to extract' }),
31	    },
32	    {
33	      id: 'grow/growth-promote', frequency: 'daily', after: ['grow/growth-extract'],
34	      outcome: 'done', codeWorkMinutes: 1, agentMinutes: 2,
35	      precondition: (w) => ({ run: !!w.promoteHasCandidates, reason: 'nothing staged' }),
36	    },
37	    {
38	      id: 'tidy/tidy-issues', frequency: 'daily', outcome: 'done',
39	      codeWorkMinutes: 1, agentMinutes: 16,
40	      precondition: (w, now) => ({
41	        run: w.issueTouchedAt != null && now - w.issueTouchedAt <= 24 * 3600e3,
42	        reason: 'no issue touched in window',
43	      }),
44	    },
45	    {
46	      id: 'chrome/store-release', frequency: 'daily', outcome: 'done', codeWorkMinutes: 3,
47	      precondition: (w) => ({ run: !!w.releasePending, reason: 'nothing to release' }),
48	    },
49	    {
50	      id: 'gcec/create-extractor', frequency: 'hourly', outcome: 'done',
51	      codeWorkMinutes: 4, agentMinutes: 10,
52	      precondition: (w) => ({ run: !!w.pendingRequest, reason: 'no eligible requests' }),
53	    },
54	    {
55	      id: 'tidy/tidy-prs', frequency: 'weekly', outcome: 'done',
56	      codeWorkMinutes: 1, agentMinutes: 5,
57	      precondition: (w) => ({ run: !!w.stalePrs, reason: 'no stale PRs' }),
58	    },
59	    { id: 'sheepdog/fleet-baseline', frequency: 'manual', outcome: 'done', codeWorkMinutes: 1, agentMinutes: 5 },
60	  ];
61	}
62	
63	// The triage-split cast (S41–S43), kept OUT of `cast()` on purpose: these two
64	// always-run tasks would add executor contention to every other scenario, and
65	// S15's mutex timing is sensitive to exactly that.
66	const SEEDS = {
67	  id: 'sheepdog/fleet-seeds', frequency: 'daily', outcome: 'done', codeWorkMinutes: 2,
68	  precondition: () => ({ run: true }),
69	  codeWorkFails: (w) => !!w.patScopeMissing,
70	  codeWorkTriage: () => 'action', // the PAT lacks Contents: write — a person grants it
71	};
72	const REGENERATE = {
73	  id: 'site/regenerate', frequency: 'daily', outcome: 'done', codeWorkMinutes: 2,
74	  precondition: () => ({ run: true }),
75	  deliversOpenPr: () => true,
76	};
77	
78	const evals = (sim, task) => sim.log.filter((e) => e.kind === 'evaluate' && e.task === task);
79	// The anchor-side ask (#1115): the scheduler run's evaluation when the anchor
80	// comes — distinct from `evals`, the executor's pick-time re-evaluation.
81	const asks = (sim, task) => sim.log.filter((e) => e.kind === 'anchor-evaluate' && e.task === task);
82	const closedOf = (sim, task) =>
83	  sim.family(task).filter((i) => !i.seeded && i.state === 'closed' && i.outcome != null);
84	
85	// ---- S1' — quiet night: one anchor-side ask per task per period, no items at
86	// all — a no creates nothing, and the board carries the verdicts (#1115).
87	test("S1' quiet night: one ask per period, no items — the board carries the verdicts", () => {
88	  const sim = makeSim({ tasks: cast() })
89	    .seedSteadyState('2026-08-12T00:00Z')
90	    .run('2026-08-12T00:00Z', '2026-08-13T00:00Z');
91	
92	  for (const task of ['basics/baselining', 'tidy/tidy-issues', 'chrome/store-release']) {
93	    assert.equal(asks(sim, task).length, 1, `${task} asked once`);
94	    assert.equal(sim.standingItem(task), undefined, `${task} filed no item`);
95	    assert.equal(sim.board.rows.get(task).verdict, 'no', `${task}'s decline is a board row`);
96	  }
97	  // the hourly task asks hourly — that is its declared cadence, not a defect
98	  assert.equal(asks(sim, 'gcec/create-extractor').length, 23);
99	  // manual tasks never instantiate
100	  assert.equal(sim.family('sheepdog/fleet-baseline').length, 0);
101	  // the executor evaluated nothing: no item ever existed to pick
102	  assert.equal(sim.log.filter((e) => e.kind === 'evaluate').length, 0);
103	  // nothing ran, nothing escalated, nothing closed
104	  assert.equal(sim.log.filter((e) => e.kind === 'handoff' || e.kind === 'escalate').length, 0);
105	});
106	
107	// ---- S2 — happy path: work exists, the item runs to a closed outcome.
108	test('S2 happy path: touched issues -> item runs, closes done', () => {
109	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
110	  sim.at('2026-08-12T04:02Z', ({ world }) => { world.issueTouchedAt = T('2026-08-12T04:02Z'); });
111	  sim.run('2026-08-12T00:00Z', '2026-08-12T12:00Z');
112	
113	  const [done] = closedOf(sim, 'tidy/tidy-issues');
114	  assert.ok(done, 'tidy-issues converged');
115	  assert.equal(done.outcome, 'done');
116	  // claimed at the 04:17 drain, agent 16m: closed ~04:34
117	  assert.ok(done.closedAt <= T('2026-08-12T04:40Z'));
118	  assert.equal(evals(sim, 'tidy/tidy-issues').length, 1);
119	});
