// one late/manual scheduler run outside the cron grid (with its post-scheduler run drain)
schedulerRunAt(isoTime) {
  schedule(T(isoTime), schedulerRun);
  schedule(T(isoTime) + 40_000, () => executorRun('E1', 'scheduler-run-drain'));
  return sim;
},

